create extension if not exists "uuid-ossp";
create type appointment_status as enum ('pending','confirmed','checked_in','in_service','completed','cancelled','no_show');
create table services(id uuid primary key default uuid_generate_v4(),slug text unique not null,name text not null,category text not null,duration_minutes int not null check(duration_minutes>0),price_etb numeric(10,2) not null check(price_etb>=0),description text,active boolean default true,created_at timestamptz default now());
create table barbers(id uuid primary key default uuid_generate_v4(),slug text unique not null,name text not null,bio text,specialties text[],active boolean default true,created_at timestamptz default now());
create table customers(id uuid primary key default uuid_generate_v4(),user_id uuid unique references auth.users(id),full_name text not null,phone text unique not null,email text,loyalty_points int not null default 0,created_at timestamptz default now());
create table appointments(id uuid primary key default uuid_generate_v4(),reference text unique not null,customer_id uuid references customers(id),service_id uuid not null references services(id),barber_id uuid references barbers(id),starts_at timestamptz not null,ends_at timestamptz not null,status appointment_status not null default 'pending',notes text,created_at timestamptz default now());
create table barber_blocks(id uuid primary key default uuid_generate_v4(),barber_id uuid not null references barbers(id),starts_at timestamptz not null,ends_at timestamptz not null,reason text);
create table loyalty_transactions(id uuid primary key default uuid_generate_v4(),customer_id uuid not null references customers(id),appointment_id uuid references appointments(id),points int not null,reason text not null,created_at timestamptz default now());
create table membership_plans(id uuid primary key default uuid_generate_v4(),name text unique not null,price_etb numeric not null,billing_period text not null,benefits jsonb not null default '[]',active boolean default true);
create table home_service_requests(id uuid primary key default uuid_generate_v4(),customer_name text not null,phone text not null,address text not null,preferred_at timestamptz,status text not null default 'requested',service_amount numeric,transport_charge numeric,additional_fee numeric,notes text);
alter table appointments add constraint appointments_no_overlap exclude using gist (barber_id with =, tstzrange(starts_at,ends_at,'[)') with &&) where (status not in ('cancelled','no_show'));
create or replace function create_appointment(p_service_slug text,p_barber_slug text,p_customer_name text,p_customer_phone text,p_start_at timestamptz,p_reference text) returns uuid language plpgsql security definer as $$ declare s services; b barbers; c customers; appointment_id uuid; begin select * into s from services where slug=p_service_slug and active; if not found then raise exception 'Service unavailable'; end if; if p_barber_slug='any' then select b.* into b from barbers b where b.active and not exists(select 1 from appointments a where a.barber_id=b.id and a.status not in ('cancelled','no_show') and tstzrange(a.starts_at,a.ends_at,'[)') && tstzrange(p_start_at,p_start_at+make_interval(mins=>s.duration_minutes),'[)')) limit 1; else select * into b from barbers where slug=p_barber_slug and active; end if; if not found then raise exception 'No barber available'; end if; insert into customers(full_name,phone) values(p_customer_name,p_customer_phone) on conflict(phone) do update set full_name=excluded.full_name returning * into c; insert into appointments(reference,customer_id,service_id,barber_id,starts_at,ends_at) values(p_reference,c.id,s.id,b.id,p_start_at,p_start_at+make_interval(mins=>s.duration_minutes)) returning id into appointment_id; return appointment_id; end $$;
